import re, os
d = '/opt/ce-work/chain/stuck-requests/ws'
starts, dones, errors = set(), set(), set()
bad_lines = []
for f in sorted(os.listdir(d + '/logs')):
    for line in open(os.path.join(d, 'logs', f)):
        m = re.search(r'req-\d+', line)
        if not m:
            if line.strip():
                bad_lines.append(line.rstrip())
            continue
        rid = m.group(0)
        for tok in re.findall(r'\b(start|done|ERROR|WARN|INFO)\b', line):
            if tok == 'start': starts.add(rid)
            elif tok == 'done': dones.add(rid)
            elif tok == 'ERROR': errors.add(rid)
stuck = sorted(r for r in starts if r in errors and r not in dones)
open(d + '/out_placeholder.txt','w').close()
os.remove(d + '/out_placeholder.txt')
print('starts:', len(starts), 'dones:', len(dones), 'errors:', len(errors))
print('stuck:', len(stuck))
print('\n'.join(stuck))
print('bad_lines:', bad_lines[:5])
